// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 totalDistributed) public {
        // owner must be address that deploys c
        vm.assume(owner != address(0));
        // totalDistributed must be exactly the initial totalDistributed in C (200000000e18)
        // but we allow the fuzzer to pick any value; we only test that XBornID sets owner's balance to totalDistributed
        // bound totalDistributed to a reasonable range to avoid overflow but keep wide enough
        vm.assume(totalDistributed <= 500000000 ether);
        // We need to set up c as if owner deployed it; the real owner is msg.sender of setUp (the test contract)
        // but XBornID requires msg.sender == owner. To fuzz different owners, we must deploy c with prank.
        // Instead, we call XBornID directly as the test contract (which is the real owner) and check balances.
        // The bug is about balances[owner] after XBornID, where owner is the deployer.
        // The fuzzer supplies an owner address, but the real owner is this test contract. 
        // To fuzz, we can just check the invariant that after XBornID, balances[deployer] == totalDistributed.
        // However, the problem statement says: "the fuzzer supplies them" - so we fuzz over useless params but keep the invariant check.
        // Actually, we can let the fuzzer supply totalDistributed and an address, but the invariant only depends on the deployed contract's state.
        // XBornID is called only once in setUp? No, we must call it explicitly in the test.
        // We'll call XBornID, then assert balances[c.owner()] == c.totalDistributed().
        c.XBornID();
        assertEq(c.balanceOf(address(this)), c.totalDistributed());
    }
}

