contract InvMutTest {
    C c;
    uint constant initialTotalDistributed = 200000000e18;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, address newOwner) public {
        // Ensure caller starts with no balance in c to avoid revert on getTokens
        require(c.balanceOf(caller) == 0);
        // Transfer ownership to a neutral address so owner is not caller
        c.transferOwnership(newOwner);
        // Let caller attempt XBornID, which on M will reset owner balance to totalDistributed
        (bool success, ) = address(c).call(abi.encodeWithSignature("XBornID()"));
        // After any calls, owner balance must not exceed totalDistributed
        // On P, XBornID is guarded by onlyOwner so it reverts unless caller is owner, thus owner balance stays <= totalDistributed
        // On M, anyone can call XBornID and repeatedly set owner balance to totalDistributed, potentially exceeding it if called after distribution increases owner balance
        assert(c.balanceOf(c.owner()) <= initialTotalDistributed);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        try c.XBornID() { reverted = false; } catch { reverted = true; }
        assert(reverted || caller == c.owner());
    }
}

